A static local starts at 10 and gains two per call. Which values appear?

#include <stdio.h>

int next(void)
{
    static int value = 10;
    value += 2;
    return value;
}

int main(void)
{
    printf("%d\n", next());
    printf("%d\n", next());
    return 0;
}
